public class Trie {
    private sealed class Node {
        public readonly Node[] next = new Node[26];   // ячейка на букву: next['c' - 'a']
        public bool end;                              // здесь кончается слово
    }

    private readonly Node root = new Node();          // корень — пустой префикс

    public void Insert(string word) {
        var node = root;
        foreach (char ch in word)
            node = node.next[ch - 'a'] ??= new Node();   // пройти по ребру или создать его
        node.end = true;                                 // «app» внутри «apple» — слово только после этого
    }

    public bool Search(string word) => Find(word)?.end == true;

    public bool StartsWith(string prefix) => Find(prefix) != null;

    private Node Find(string s) {
        var node = root;
        foreach (char ch in s) {
            node = node.next[ch - 'a'];
            if (node == null) return null;   // нет ребра: ни одно слово так не продолжается
        }
        return node;
    }
}

