int[] next = new int[maxNodes * 26];
bool[] end = new bool[maxNodes];
int count = 1;                                       // узел 0 — корень

void Insert(string w) {
    int v = 0;
    foreach (char ch in w) {
        int c = ch - 'a';
        if (next[v * 26 + c] == 0) next[v * 26 + c] = count++;   // 0 — ребра нет
        v = next[v * 26 + c];
    }
    end[v] = true;
}

int Find(string s) {                                 // -1 — пути нет
    int v = 0;
    foreach (char ch in s) {
        v = next[v * 26 + (ch - 'a')];
        if (v == 0) return -1;
    }
    return v;
}

