// до k слов с префиксом: спуск к узлу префикса, потом обход в глубину
void Collect(Node node, StringBuilder sb, List<string> res, int k) {
    if (res.Count == k) return;
    if (node.end) res.Add(sb.ToString());
    for (int c = 0; c < 26 && res.Count < k; c++) {
        if (node.next[c] == null) continue;
        sb.Append((char)('a' + c));
        Collect(node.next[c], sb, res, k);
        sb.Length--;                     // вернуть букву: один StringBuilder на весь обход
    }
}
